import { GoogleGenAI } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.GEMINI_API_KEY });
const model = process.env.GEMINI_MODEL; // verify current ids: https://ai.google.dev/gemini-api/docs/models
if (!model) throw new Error("GEMINI_MODEL is not configured");

type Outcome = { state: "completed" | "failed_safely" | "budget_exceeded"; detail: string };

// Stateless mode: the application holds the history and replays the returned steps each turn.
async function runToolLoop(request: string, principal: Principal): Promise<Outcome> {
  const MAX_TURNS = 6;
  const MAX_TOOL_CALLS = 10;
  const deadline = Date.now() + 60_000;
  let toolCalls = 0;
  const history: unknown[] = [{ type: "user_input", content: [{ type: "text", text: request }] }];

  for (let turn = 1; turn <= MAX_TURNS; turn++) {
    if (Date.now() > deadline) return { state: "budget_exceeded", detail: "deadline" };
    const interaction = await ai.interactions.create({ model, input: history, tools, store: false });
    if (interaction.status !== "completed") return { state: "failed_safely", detail: interaction.status };

    const calls = interaction.steps.filter((step) => step.type === "function_call");
    if (calls.length === 0) return { state: "completed", detail: interaction.output_text ?? "" };

    history.push(...interaction.steps);
    for (const call of calls) {
      if (++toolCalls > MAX_TOOL_CALLS) return { state: "budget_exceeded", detail: "tool calls" };
      // Complete, validated arguments only; never execute partial streamed deltas.
      const result = await validateAuthorizeAndRun(call.name, call.arguments, principal);
      history.push({
        type: "function_result",
        name: call.name,
        call_id: call.id, // the result is matched to its call by id, not by position
        result: [{ type: "text", text: JSON.stringify(result) }],
      });
    }
  }
  return { state: "budget_exceeded", detail: "max turns" };
}

// Handler behind the set_training_status declaration. It returns a function_result either way,
// so the model can explain the outcome, but authority is decided here, not by the model.
async function handleSetTrainingStatus(call: { id: string; name: string; arguments: Record<string, unknown> }, principal: Principal) {
  const args = parseSetTrainingStatus(call.arguments); // rejects unknown fields and bad enums

  // Identity comes from the authenticated session; learnerId in the arguments is only a claim.
  const decision = await authorize(principal, "transcript:write", args.learnerId, args.moduleId);
  await auditAuthorization(principal, call.id, decision);

  let outcome: { status: string; operationId?: string };
  if (!decision.allowed) {
    outcome = { status: "refused" };
  } else if (args.status === "completed" && !(await hasFreshApproval(principal, args.operationId))) {
    outcome = { status: "needs_approval", operationId: args.operationId };
  } else if (await pendingReconciliation(args.operationId)) {
    outcome = { status: "outcome_unknown", operationId: args.operationId }; // no retry until reconciled
  } else {
    outcome = await writeAndVerify(args); // idempotent write keyed by operationId, then read back
  }

  return {
    type: "function_result",
    name: call.name,
    call_id: call.id,
    result: [{ type: "text", text: JSON.stringify(outcome) }],
  };
}

async function writeAndVerify(args: SetTrainingStatusArgs) {
  try {
    await transcripts.setStatus(args, { idempotencyKey: args.operationId, timeoutMs: 5_000 });
  } catch (error) {
    if (isTimeout(error)) {
      await markPendingReconciliation(args.operationId); // the write may have been accepted
      return { status: "outcome_unknown", operationId: args.operationId };
    }
    throw error;
  }
  const stored = await transcripts.getStatus(args.learnerId, args.moduleId); // the postcondition, not the handler's word
  return { status: stored === args.status ? "completed" : "outcome_unknown", operationId: args.operationId };
}

// Known steps and branches: a deterministic workflow. The model fills one bounded step.
async function enrollmentReminderWorkflow(learnerId: string) {
  const enrollment = await getEnrollment(learnerId); // code decides what runs, and in what order
  if (enrollment.status === "completed") return "completed";
  const draft = await draftReminderWithGemini(enrollment); // one model call, no tools
  return (await instructorApproves(draft)) ? sendReminder(learnerId, draft) : "needs_approval";
}

// Path depends on what tools reveal: a bounded agent, with every limit written down.
// Frameworks such as ADK can host this, but they do not grant authority on their own.
type Terminal = "completed" | "needs_approval" | "refused" | "failed_safely" | "cancelled" | "budget_exceeded" | "outcome_unknown";

const labSupportAgent = {
  objective: "Diagnose why a learner's lab submission fails the autograder and suggest a fix",
  allowedTools: ["get_submission", "get_autograder_log", "search_course_notes"], // reads only
  dataScope: "the requesting learner's own submissions",
  budgets: { maxTurns: 8, maxToolCalls: 12, maxSeconds: 120, maxTotalTokens: 60_000 },
  checkpoints: ["human review before any suggestion that edits files"],
  audit: "every function_call step and result stored under the trace id",
  rollback: "agent disabled by flag; the workflow above remains the fallback",
  terminalStates: [
    "completed",
    "needs_approval",
    "refused",
    "failed_safely",
    "cancelled",
    "budget_exceeded",
    "outcome_unknown",
  ] satisfies Terminal[],
  promotionEvidence: "beats the workflow on the evaluation set without new critical failures",
};
